CREATE TABLE employee_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id), employee_number text NOT NULL UNIQUE, employment_status text NOT NULL DEFAULT 'active', ciphertext bytea NOT NULL, iv bytea NOT NULL, auth_tag bytea NOT NULL, key_id text NOT NULL, start_date date, end_date date, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE employee_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_profile_id uuid NOT NULL REFERENCES employee_profiles(id), store_id uuid REFERENCES stores(id), department_id uuid REFERENCES departments(id), manager_employee_profile_id uuid REFERENCES employee_profiles(id), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (store_id IS NOT NULL OR department_id IS NOT NULL));
CREATE INDEX employee_assignments_employee_id_idx ON employee_assignments (employee_profile_id) WHERE effective_to IS NULL;
